// The fixture was generated by the actual upstream 1dd75e9 runtime. Its format
// marker is 11, with additive append columns and events, and without schedules.
// These combinations postdate the recovered implementation's fixtures.
func TestGoalMigrationCurrentUpstreamPreservesAppendAndAvailability(t *testing.T) {
	for _, dormant := range []bool{false, true} {
		t.Run(fmt.Sprint(dormant), func(t *testing.T) {
			ctx := celltest.Context(context.Background())
			path := filepath.Join(t.TempDir(), "upstream.db")
			db, err := sql.Open(sqliteDriverName, path)
			require.NoError(t, err)
			fixture, err := os.ReadFile("testdata/goal-upstream-11.sql")
			require.NoError(t, err)
			_, err = db.Exec(string(fixture))
			require.NoError(t, err)
			if dormant {
				ddl, err := os.ReadFile("testdata/unused-schedules.sql")
				require.NoError(t, err)
				_, err = db.Exec(string(ddl))
				require.NoError(t, err)
				_, err = db.Exec(`INSERT INTO jobdb_schedules(tenant_id,schedule_id,state,generation,spec_hash,trigger_json,target_json,cell_id,cell_name,cell_repo,target_job_type,overlap_policy,failure_policy_json,created_at_ns,updated_at_ns)
SELECT tenant_id,'dormant','PAUSED',1,'historical',x'7b7d',x'7b7d',cell_id,name,repo,'work','serial',x'7b7d',1,1 FROM jobdb_cells`)
				require.NoError(t, err)
			}
			before := compatibilitySnapshot(t, db)
			columns := []string{}
			rows, err := db.Query(`SELECT name FROM pragma_table_info('jobdb_jobs') ORDER BY cid`)
			require.NoError(t, err)
			for rows.Next() {
				var name string
				require.NoError(t, rows.Scan(&name))
				columns = append(columns, `"`+name+`"`)
			}
			require.NoError(t, rows.Close())
			query := `SELECT rowid,` + strings.Join(columns, ",") + ` FROM jobdb_jobs ORDER BY job_id`
			jobs := storedQuery(t, db, query)
			check, err := CheckGoalMigration(ctx, path)
			require.NoError(t, err, "%+v", check.Issues)
			require.Equal(t, 11, check.SourceFormat)
			require.Equal(t, before, compatibilitySnapshot(t, db), "check must be read-only")
			_, err = NewFromConfig(ctx, Config{Projects: celltest.UnrestrictedProjects{}, DBPath: path})
			require.ErrorIs(t, err, ErrMigrationRequired)
			require.Equal(t, before, compatibilitySnapshot(t, db), "constructor must refuse without conversion")
			report, err := MigrateGoals(ctx, path)
			require.NoError(t, err, "%+v", report.Issues)
			require.Equal(t, "MIGRATED", report.Verdict)
			require.Equal(t, jobs, storedQuery(t, db, query), "every original job column and rowid must survive")
			after := compatibilitySnapshot(t, db)
			for table, values := range before {
				if table != "jobdb_jobs" && table != "jobdb_goals" && table != "jobdb_goal_candidates" {
					require.Equal(t, values, after[table], table)
				}
			}
			var schedules int
			require.NoError(t, db.QueryRow(`SELECT count(*) FROM sqlite_master WHERE name='jobdb_schedules'`).Scan(&schedules))
			require.Equal(t, map[bool]int{false: 0, true: 1}[dormant], schedules)
			require.NoError(t, db.Close())
			r, err := NewFromConfig(ctx, Config{Projects: celltest.UnrestrictedProjects{}, DBPath: path})
			require.NoError(t, err)
			defer r.Close(ctx)
			key := jobdb.JobKey{TenantId: "tenant", JobId: "saved"}
			saved, err := r.ListJobs(ctx, jobdb.ListJobsRequest{TenantIds: []string{"tenant"}, JobKeys: []jobdb.JobKey{key}})
			require.NoError(t, err)
			require.Len(t, saved.Jobs, 1)
			require.Equal(t, time.Date(2030, 1, 2, 3, 4, 5, 123456789, time.UTC), saved.Jobs[0].AvailableAt)
			assertStartArtifact(t, ctx, r, key, "saved.bin", []byte("saved upstream artifact"))
			page, err := r.ListJobs(ctx, jobdb.ListJobsRequest{TenantIds: []string{"tenant"}, AppendKeys: []string{"saved-chain"}})
			require.NoError(t, err)
			require.Len(t, page.Jobs, 1)
			original := page.Jobs[0].JobKey
			appended, err := r.StartOrAppendJob(ctx, jobdb.StartOrAppendJobRequest{Job: jobdb.StartOrAppendJob{AppendKey: "saved-chain", Job: jobdb.SubmitJob{TenantId: "tenant", Cell: "work", JobType: "batch", Data: jobdb.NewTaskDataOrPanic("unused")}, Append: []byte(`{"number":2}`)}})
			require.NoError(t, err)
			require.Equal(t, original, appended.JobKey, "continue the existing append generation")
			check, err = CheckGoalMigration(ctx, path)
			require.NoError(t, err)
			require.Equal(t, "CURRENT", check.Verdict)
		})
	}
}

func TestGoalMigrationRejectsBrokenAppendPreparation(t *testing.T) {
	for _, mutation := range []string{
		`UPDATE jobdb_goal_preparations SET descriptor='{"kind":"start-or-append","id":"different"}' WHERE job_id='Xt9QGUa7Xy2uAuAAh6ynh9EdfAf'`,
		`UPDATE jobdb_goal_preparations SET share_goal=1 WHERE job_id='Xt9QGUa7Xy2uAuAAh6ynh9EdfAf'`,
		`UPDATE jobdb_jobs SET append_gen=0 WHERE job_id='Xt9QGUa7Xy2uAuAAh6ynh9EdfAf'`,
		`ALTER TABLE jobdb_jobs DROP COLUMN append_gen`,
	} {
		t.Run(mutation, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "broken.db")
			db, err := sql.Open(sqliteDriverName, path)
			require.NoError(t, err)
			defer db.Close()
			fixture, err := os.ReadFile("testdata/goal-upstream-11.sql")
			require.NoError(t, err)
			_, err = db.Exec(string(fixture))
			require.NoError(t, err)
			if strings.HasPrefix(mutation, "ALTER") {
				_, err = db.Exec(`DROP INDEX jobdb_jobs_append_idx`)
				require.NoError(t, err)
			}
			_, err = db.Exec(mutation)
			require.NoError(t, err)
			before, schema := compatibilitySnapshot(t, db), schemaSnapshot(t, db)
			_, err = CheckGoalMigration(context.Background(), path)
			require.ErrorIs(t, err, ErrGoalMigrationBlocked)
			_, err = MigrateGoals(context.Background(), path)
			require.ErrorIs(t, err, ErrGoalMigrationBlocked)
			require.Equal(t, before, compatibilitySnapshot(t, db))
			require.Equal(t, schema, schemaSnapshot(t, db))
		})
	}
}

func TestGoalMigrationPreservesEventExtensionsAndSequence(t *testing.T) {
	path, db := migrationFixture(t, 12, true, true, true)
	_, err := db.Exec(`
INSERT INTO jobdb_lease_events(event_id,tenant_id,job_id,event_type,occurred_at_ns,cell_id,cell_name,cell_repo,goal_id,job_type,route_job_type,route_task_type,lease_id,worker_id,lease_expires_at_ns,acquisition_source)
VALUES(42,'tenant','producer','lease_acquired',1,'cell','original','example.test/original','H','work','work','','saved','worker',2,'poll');
UPDATE sqlite_sequence SET seq=99 WHERE name='jobdb_lease_events';
CREATE TABLE event_audit(value TEXT);
CREATE INDEX application_event_idx ON jobdb_lease_events(worker_id,event_id);
CREATE TRIGGER application_event_trigger AFTER UPDATE ON jobdb_lease_events BEGIN INSERT INTO event_audit VALUES(NEW.worker_id); END;
CREATE VIEW application_events AS SELECT event_id FROM jobdb_lease_events;
CREATE TABLE application_event_refs(event_id INTEGER REFERENCES jobdb_lease_events(event_id));
INSERT INTO application_event_refs VALUES(42)`)
	require.NoError(t, err)
	before := compatibilitySnapshot(t, db)
	definitions := storedQuery(t, db, `SELECT name,sql FROM sqlite_master WHERE name LIKE 'application_event%' ORDER BY name`)
	report, err := MigrateGoals(context.Background(), path)
	require.NoError(t, err, "%+v", report.Issues)
	after := compatibilitySnapshot(t, db)
	for _, table := range []string{"jobdb_lease_events", "event_audit", "application_event_refs"} {
		require.Equal(t, before[table], after[table], table)
	}
	require.Equal(t, definitions, storedQuery(t, db, `SELECT name,sql FROM sqlite_master WHERE name LIKE 'application_event%' ORDER BY name`))
	var seq, id int64
	require.NoError(t, db.QueryRow(`SELECT seq FROM sqlite_sequence WHERE name='jobdb_lease_events'`).Scan(&seq))
	require.Equal(t, int64(99), seq)
	require.NoError(t, db.QueryRow(`SELECT event_id FROM application_events`).Scan(&id))
	require.Equal(t, int64(42), id)
	_, err = db.Exec(`UPDATE jobdb_lease_events SET worker_id='after' WHERE event_id=42`)
	require.NoError(t, err)
	var worker string
	require.NoError(t, db.QueryRow(`SELECT value FROM event_audit`).Scan(&worker))
	require.Equal(t, "after", worker)
}
